function draw(g, t, p, env) {
  const b = env.box;
  const u = clamp(t / p.inDur, 0, 1);
  const e = ease.outCubic(u);
  const x = b.x - (1 - e) * (b.w + 120);
  const y = b.y;
  g.begin();
  g.roundRect(x, y, b.w, b.h, 18);
  g.fill({color: p.cardColor, alpha: 0.94});
  g.begin();
  g.roundRect(x + 24, y + 30, 6, b.h - 60, 3);
  g.fill({color: p.accent});
  const avail = b.w - 108;
  let fs = p.size;
  const tw = g.measure(p.text, {size: fs, weight: 800, font: 'sans'});
  if (tw > avail && tw > 0) fs = Math.max(20, fs * avail / tw);
  g.text(p.text, x + 52, y + b.h / 2 - 14, {size: fs, weight: 800, font: 'sans', color: p.textColor, align: 'left', baseline: 'middle'});
  const u2 = clamp((t - p.inDur * 0.7) / 0.5, 0, 1);
  const lw = avail * ease.outCubic(u2);
  if (lw > 1) {
    g.begin();
    g.rect(x + 52, y + b.h - 48, lw, 4);
    g.fill({color: p.accent});
  }
}

function draw(g, t, p, env) {
  const b = env.box;
  const u = clamp(t / p.inDur, 0, 1);
  const e = ease.outCubic(u);
  const bob = u >= 1 ? Math.sin((t - p.inDur) * 3) * 6 : 0;
  const pulse = u >= 1 ? 0.75 + 0.25 * Math.sin((t - p.inDur) * 4) : 1;
  const tipX = b.x + b.w * 0.5;
  const tipY = b.y + b.h * 0.5;
  const x0 = b.x - 300, y0 = b.y - 190;
  const cx = b.x - 60, cy = b.y - 230;
  const x1 = tipX, y1 = tipY;
  const steps = Math.max(2, Math.floor(e * 28));
  g.save();
  g.translate(0, bob);
  g.glow({color: p.color, blur: 26 * pulse});
  g.begin();
  for (let i = 0; i <= steps; i++) {
    const s = i / 28, ix = 1 - s;
    const x = ix * ix * x0 + 2 * ix * s * cx + s * s * x1;
    const y = ix * ix * y0 + 2 * ix * s * cy + s * s * y1;
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke({color: p.color, width: p.width + 8, cap: 'round', join: 'round', alpha: 0.35 * pulse});
  g.begin();
  for (let i = 0; i <= steps; i++) {
    const s = i / 28, ix = 1 - s;
    const x = ix * ix * x0 + 2 * ix * s * cx + s * s * x1;
    const y = ix * ix * y0 + 2 * ix * s * cy + s * s * y1;
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke({color: p.color, width: p.width, cap: 'round', join: 'round'});
  g.glow(null);
  g.begin();
  for (let i = 0; i <= steps; i++) {
    const s = i / 28, ix = 1 - s;
    const x = ix * ix * x0 + 2 * ix * s * cx + s * s * x1;
    const y = ix * ix * y0 + 2 * ix * s * cy + s * s * y1;
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke({color: '#ffffff', width: Math.max(3, p.width * 0.38), cap: 'round', join: 'round', alpha: 0.85});
  if (e > 0.8) {
    const hs = clamp((e - 0.8) / 0.2, 0, 1);
    const tx = 2 * (x1 - cx), ty = 2 * (y1 - cy);
    const ang = Math.atan2(ty, tx);
    const len = 52 * hs, wid = 26 * hs;
    const bx = tipX - Math.cos(ang) * len, by = tipY - Math.sin(ang) * len;
    const px = Math.cos(ang + Math.PI / 2), py = Math.sin(ang + Math.PI / 2);
    g.glow({color: p.color, blur: 22 * pulse});
    g.begin();
    g.moveTo(tipX, tipY);
    g.lineTo(bx + px * wid, by + py * wid);
    g.lineTo(bx - px * wid, by - py * wid);
    g.close();
    g.fill({color: p.color});
    g.glow(null);
  }
  g.restore();
}

function draw(g, t, p, env) {
  const b = env.box, u = clamp(t / p.inDur, 0, 1), s = ease.outBack(u), fade = clamp((env.duration - t) / 0.25, 0, 1);
  if (s <= 0.001) return;
  const font = {size: p.size, weight: 700};
  const w = g.measure(p.text, font) + p.size * 1.2, h = p.size * 1.7, tail = p.size * 0.55;
  const cx = b.x + b.w / 2, cy = b.y + b.h / 2;
  let x = cx, y = cy, tx = cx, ty = cy;  // 標籤中心與尖角指的點
  if (p.side === 'above') { y = b.y - tail - h / 2; ty = b.y - 4; }
  else if (p.side === 'below') { y = b.y + b.h + tail + h / 2; ty = b.y + b.h + 4; }
  else if (p.side === 'left') { x = b.x - tail - w / 2; tx = b.x - 4; }
  else { x = b.x + b.w + tail + w / 2; tx = b.x + b.w + 4; }
  x = clamp(x, w / 2 + 8, env.width - w / 2 - 8); y = clamp(y, h / 2 + 8, env.height - h / 2 - 8);
  const ax = tx - x, ay = ty - y, vertical = p.side === 'above' || p.side === 'below';
  // 以尖角為中心彈出，再把原點移回標籤中心
  g.save(); g.alpha(fade); g.translate(tx, ty); g.scale(s, s); g.translate(-ax, -ay);
  g.glow({color: '#00000066', blur: 14});
  g.begin(); g.roundRect(-w / 2, -h / 2, w, h, h * 0.3); g.fill({color: p.color});
  g.begin();
  if (vertical) { const by = Math.sign(ay) * (h / 2 - 1); g.moveTo(-tail * 0.6, by); g.lineTo(ax, ay); g.lineTo(tail * 0.6, by); }
  else { const bx = Math.sign(ax) * (w / 2 - 1); g.moveTo(bx, -tail * 0.6); g.lineTo(ax, ay); g.lineTo(bx, tail * 0.6); }
  g.close(); g.fill({color: p.color});
  g.glow(null);
  g.text(p.text, 0, 0, {size: p.size, weight: 700, color: p.textColor});
  g.restore();
}

