function update(t, env) {
  const pop = Math.min(1, t / 0.55); const ease = 1 - Math.pow(1 - pop, 3);
  const s = env.params.size * ease * (1 + 0.08 * Math.sin(Math.min(1, pop) * Math.PI));
  S.trophy.scale.setScalar(Math.max(0.001, s));
  S.trophy.position.set(S.center.x, S.center.y + Math.sin(t * 1.3) * 0.16, S.center.z);
  S.trophy.rotation.y = t * env.params.spinSpeed * Math.PI * 2 * 0.45;
  S.trophy.rotation.z = Math.sin(t * 1.1) * 0.05;
  for (let i = 0; i < S.count; i++) {
    const r1 = env.rand(i * 3 + 1); const r2 = env.rand(i * 3 + 2); const r3 = env.rand(i * 3 + 3);
    const ang = t * (0.7 + r3 * 0.7) + i * 2.39996;
    const rad = (1.35 + r1 * 0.85) * env.params.size;
    const yOff = (r2 - 0.5) * 2.4 * env.params.size + Math.sin(t * 1.7 + i) * 0.12;
    S.dummy.position.set(S.center.x + Math.cos(ang) * rad, S.center.y + yOff, S.center.z + Math.sin(ang) * rad * 0.45);
    const tw = 0.55 + 0.65 * (0.5 + 0.5 * Math.sin(t * 3.2 + i * 1.7));
    S.dummy.scale.set(tw * ease, tw * ease * 1.7, tw * ease);
    S.dummy.rotation.set(t * 1.5 + i, t * 2.0 + i * 0.6, 0);
    S.dummy.updateMatrix(); S.sparkles.setMatrixAt(i, S.dummy.matrix);
  }
  S.sparkles.instanceMatrix.needsUpdate = true;
  S.sparkles.material.opacity = 0.75 + 0.25 * Math.sin(t * 2.4);
}

function draw(g, t, p, env) {
  const b = env.box, u = ease.outCubic(clamp(t / p.inDur, 0, 1)), fade = clamp((env.duration - t) / 0.25, 0, 1);
  const h = b.h * p.thickness, y = b.y + (b.h - h) / 2, x0 = b.x - 6, w = (b.w + 12) * u;
  if (w <= 1) return;
  g.save(); g.alpha(fade * p.opacity);
  g.begin();
  g.moveTo(x0, y + env.rand(1) * 4); g.lineTo(x0 + w, y + env.rand(2) * 4);
  g.lineTo(x0 + w - 4, y + h - env.rand(3) * 4); g.lineTo(x0 + 3, y + h - env.rand(4) * 4); g.close();
  g.fill({color: p.color});
  g.restore();
}

function draw(g, t, p, env) {
  const b = env.box, u = clamp(t / p.inDur, 0, 1), fade = clamp((env.duration - t) / 0.25, 0, 1);
  const cx = b.x + b.w / 2, cy = b.y + b.h / 2, rx = b.w / 2 + p.padding, ry = b.h / 2 + p.padding;
  // 起伏與起點由 env.rand 決定：同一段動畫每一格都一樣，預覽與輸出相同
  const ph = env.rand(1) * 6.28, start = -2.2 + env.rand(2) * 0.4, steps = 56;
  g.save(); g.alpha(fade);
  if (p.shadow) g.glow({color: '#00000066', blur: 8});
  g.begin();
  for (let i = 0; i <= steps; i++) {
    const a = start + (i / steps) * Math.PI * 2 * 1.1;
    const k = 1 + 0.045 * Math.sin(a * 3 + ph) + 0.02 * Math.sin(a * 7 + ph * 2) + (i / steps) * 0.06;
    const x = cx + Math.cos(a) * rx * k, y = cy + Math.sin(a) * ry * k;
    if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
  }
  g.stroke({color: p.color, width: p.width, progress: ease.inOutQuad(u)});
  g.restore();
}

function sound(a, p, env) {
