  a.noise({dur: 0.02, gain: p.volume * 0.35, attack: 0.001, release: 0.015, filter: {type: 'highpass', freq: 2500}});
}

function draw(g, t, p, env) {
  const b = env.box, s = Math.min(b.w, b.h) * 0.8, cx = b.x + b.w / 2, cy = b.y + b.h / 2;
  const u = clamp(t / p.inDur, 0, 1), fade = clamp((env.duration - t) / 0.25, 0, 1);
  g.save(); g.alpha(fade);
  if (p.shadow) g.glow({color: '#00000080', blur: 10});
  if (p.ring) {
    g.begin(); g.circle(cx, cy, s / 2); g.fill({color: p.color, alpha: 0.2 * ease.outCubic(u)});
    g.begin(); g.circle(cx, cy, s / 2); g.stroke({color: p.color, width: p.width * 0.6, progress: ease.outCubic(u)});
  }
  const k = ease.outCubic(clamp((t - p.inDur * 0.35) / (p.inDur * 0.65), 0, 1));
  if (k > 0) {
    g.begin(); g.moveTo(cx - s * 0.27, cy + s * 0.02); g.lineTo(cx - s * 0.07, cy + s * 0.22); g.lineTo(cx + s * 0.29, cy - s * 0.2);
    g.stroke({color: p.color, width: p.width, cap: 'round', join: 'round', progress: k});
  }
  g.restore();
}

function sound(a, p, env) {
  const notes = [1047, 1319, 1568];
  for (let i = 0; i < notes.length; i++) {
    const last = i === notes.length - 1;
    a.tone({type: 'triangle', freq: notes[i], at: i * 0.09, dur: last ? 0.5 : 0.22, gain: p.volume, attack: 0.004, release: last ? 0.42 : 0.15});
  }
}

function draw(g, t, p, env) {
  const b = env.box, cx = b.x + b.w / 2, cy = b.y + b.h / 2;
  const reach = Math.max(120, Math.max(b.w, b.h)) * p.spread;
  const end = clamp((env.duration - t) / 0.3, 0, 1);
  g.save(); g.alpha(end);
  for (let i = 0; i < p.count; i++) {
    const delay = env.rand(i * 5) * 0.15, local = t - delay;
    if (local < 0 || local > p.life) continue;
    const u = local / p.life, a = env.rand(i * 5 + 1) * Math.PI * 2, speed = 0.55 + env.rand(i * 5 + 2) * 0.45;
    const dist = reach * speed * ease.outCubic(clamp(u * 1.6, 0, 1));
    const x = cx + Math.cos(a) * dist, y = cy + Math.sin(a) * dist * 0.8 + p.gravity * 900 * local * local * 0.35;
    const size = 18 + env.rand(i * 5 + 3) * 16, spin = (env.rand(i * 5 + 4) - 0.5) * 14 * local;
    g.save(); g.translate(x, y); g.rotate(spin); g.scale(1, Math.cos(local * 9 + i));
    g.begin(); g.rect(-size / 2, -size / 4, size, size / 2);
    g.fill({color: i % 2 === 0 ? p.color : p.accent, alpha: 1 - ease.inCubic(u)});
    g.restore();
  }
  g.restore();
}

function sound(a, p, env) {
  const notes = [2093, 2637, 3136, 3951, 2349, 2794, 3520];
  for (let i = 0; i < notes.length; i++) {
    a.tone({type: 'sine', freq: notes[i], at: i * 0.055, dur: 0.18, gain: p.volume * (1 - i * 0.1), attack: 0.002, release: 0.16, pan: (i % 2 ? 0.4 : -0.4)});
  }
}

'use strict';
/** 3D 場景的鏡頭關鍵幀內插（spec §5.8；經典腳本，全域 CAMERA3D，串在場景插件前面送進沙盒，Vitest 用 vm 測）。
 *  關鍵幀 {t（相對區段開頭的秒數）, position [x,y,z], target [x,y,z]（看向的點）, fov（垂直視角，度）}；
 *  兩個關鍵幀之間用 smoothstep（慢進慢出），第一個之前停在第一個、最後一個之後停在最後一個。 */
const CAMERA3D = (() => {
  /** 慢進慢出 */
  const smooth = (u) => { const x = Math.min(1, Math.max(0, u)); return x * x * (3 - 2 * x); };
  /** 向量線性內插 */
  const mix = (a, b, k) => a.map((v, i) => v + (b[i] - v) * k);

  /** 時間 t 的鏡頭；沒有關鍵幀回 null */
  function cameraAt(keys, t) {
    if (!keys || !keys.length) return null;
    const ks = [...keys].sort((a, b) => a.t - b.t);
    const pick = (k) => ({ position: [...k.position], target: [...k.target], fov: k.fov });
    if (t <= ks[0].t) return pick(ks[0]);
    for (let i = 1; i < ks.length; i++) {
      const a = ks[i - 1], b = ks[i];
      if (t < b.t) {
        const k = smooth((t - a.t) / (b.t - a.t));
        return { position: mix(a.position, b.position, k), target: mix(a.target, b.target, k), fov: a.fov + (b.fov - a.fov) * k };
      }
    }
    return pick(ks[ks.length - 1]);
  }

  return { cameraAt };
})();

